import { createSignal, For } from "solid-js";

import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";

import { Button } from "../components/button";
import { HeroButton } from "../components/hero-button";

import { ListItem } from "./list-item";

import type { Component } from "solid-js";

// This is outside the component, so it will be stored globally
const [items, setItems] = createSignal<string[]>([], { equals: false });

export const ListExample: Component = () => {
	// By setting "equals: false", the array will always updates the value
	// This allows us to mutate the array instead of pushing a new array every time
	// This may improve performance with large arrays and we should probably create a createArraySignal utility function

	const [itemId, setItemId] = createSignal(1, { equals: false });

	function addItem() {
		const itemList = items();

		// Set the name of the new item to itemId+1
		itemList.push(`Item ${setItemId((id) => id + 1)}`);

		// Force the array to update with mutations
		setItems(itemList);
	}

	function removeItem(index: number) {
		const itemList = items();

		// Remove the item from the array
		itemList.splice(index, 1);

		// Force the array to update with mutations
		setItems(itemList);
	}

	return (
		<div class="img-dropdown-box flex flex-col m-2 my-1 w-174 pb-2">
			<HeroButton onActivate={() => addItem()}>Add Item {itemId() + 1}</HeroButton>
			<ScrollArea
				class="max-h-200"
				useProxy={true}
			>
				<For
					each={items()}
					fallback={<div class="m-2">Please Add Items...</div>}
				>
					{(item, index) => (
						<div class="flex flex-row">
							<ListItem
								name={item}
								value={index().toString()}
							/>
							{/* Note the index is REACTIVE - this means the index will be updated as the array mutates! */}
							<Button
								class={`my-2 item-${index()}`}
								onActivate={() => removeItem(index())}
							>
								Remove
							</Button>
						</div>
					)}
				</For>
			</ScrollArea>
		</div>
	);
};
